mapper.select:
select

from credit_ubo mt

     and mt.id = #{id}
     and mt.shop_id = #{shopId}
     and mt.auth_type = #{authType}
     and mt.id_doc_front_url = #{idDocFrontUrl}
     and mt.id_doc_back_url = #{idDocBackUrl}
     and mt.address_type = #{addressType}
     and mt.address_doc_url = #{addressDocUrl}
     and mt.ubo_email = #{uboEmail}
     and mt.create_time = #{createTime}
     and mt.update_time = #{updateTime}

order by mt.id desc
